<template>
  <div class="carolina-blue-page">
    <h1 id="head">Carolina Blue</h1>
    <p class="subtitle">University of North Carolina at Chapel Hill</p>

    <div class="map-wrapper" ref="mapWrapper">
      <div id="unc-map" ref="mapEl"></div>

      <!-- Popup anchored to the pin -->
      <transition name="popup-fade">
        <div
          v-if="selectedPlace"
          class="map-popup"
          :style="popupStyle"
          @mouseenter="cancelClose"
          @mouseleave="scheduleClose"
        >
          <button class="popup-close" @click="closePopup">✕</button>
          <p class="popup-name">{{ currentPlace.name }}</p>
          <div class="popup-grid" :style="{ gridTemplateColumns: `repeat(${currentPlace.photos.length}, 1fr)` }">
            <div
              v-for="(photo, i) in currentPlace.photos"
              :key="i"
              class="popup-slot"
              :class="{ clickable: photo.src }"
              @click="photo.src && openLightbox(i)"
            >
              <img v-if="photo.src" :src="photo.src" :alt="photo.caption" />
              <div v-else class="popup-placeholder"></div>
              <p class="popup-caption">{{ photo.caption }}</p>
            </div>
          </div>
          <div class="popup-tail"></div>
        </div>
      </transition>

      <p v-if="tileError" class="map-error" role="status">The map tiles could not be loaded. <button @click="retryTiles">Retry</button> · <a href="https://www.openstreetmap.org/#map=16/35.9116/-79.0456" target="_blank" rel="noopener noreferrer">Open campus map</a></p>
      <p class="map-hint">3D buildings · Right-drag to rotate · Scroll to zoom · Hover or tap a photo</p>
    </div>

    <!-- Lightbox -->
    <transition name="fade">
      <div v-if="lightbox.open" class="lightbox" @click.self="closePopup">
        <div class="lightbox-content">
          <button class="lb-close" @click="closePopup">✕</button>
          <img :src="currentPlace.photos[lightbox.index].src" :alt="currentPlace.photos[lightbox.index].caption" />
          <button v-if="currentPlace.photos.length > 1" class="lb-nav lb-prev" @click="lightbox.index = (lightbox.index - 1 + currentPlace.photos.length) % currentPlace.photos.length">&#8592;</button>
          <button v-if="currentPlace.photos.length > 1" class="lb-nav lb-next" @click="lightbox.index = (lightbox.index + 1) % currentPlace.photos.length">&#8594;</button>
          <p class="lb-meta">
            <span class="lb-place">{{ currentPlace.name }}</span>
            <span v-if="currentPlace.photos[lightbox.index].caption"> · {{ currentPlace.photos[lightbox.index].caption }}</span>
            <span v-if="currentPlace.photos.length > 1" class="lb-count"> ({{ lightbox.index + 1 }}/{{ currentPlace.photos.length }})</span>
          </p>
        </div>
      </div>
    </transition>

    <p id="ending">UNC Chapel Hill / Exchange Spring 2026</p>
    <router-link to="/illusion" class="back-link">← Back to Photos</router-link>
  </div>
</template>

<script>
import { Map as MapLibreMap, Marker, NavigationControl, setWorkerUrl } from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';

setWorkerUrl(new URL('maplibre-gl/dist/maplibre-gl-worker.mjs', import.meta.url).href);

const BRIGHT_STYLE = 'https://tiles.openfreemap.org/styles/bright';

const SLOT_W   = 200;
const SLOT_GAP = 8;
const POPUP_PAD = 28;

const PLACES = {
  'kenan-residence': {
    name: 'Kenan Residence Hall',
    latlng: [35.9145912, -79.0474981],
    photos: [
      { src: '/img/carolina/kenan1.jpeg', caption: 'Front gate' },
      { src: '/img/carolina/kenan2.jpeg', caption: 'In my room' },
    ],
  },
  'hooker-fields': {
    name: 'Hooker Fields',
    latlng: [35.91006, -79.04451],
    photos: [
      { src: '/img/carolina/hooker1.jpeg', caption: 'Holimoli' },
    ],
  },
  'coker-arboretum': {
    name: 'Coker Arboretum',
    latlng: [35.913750, -79.048972],
    photos: [
      { src: '/img/carolina/coker1.jpeg', caption: 'Purple flow' },
    ],
  },
  'polk-place': {
    name: 'Polk Place',
    latlng: [35.9109, -79.0504],
    photos: [
       { src: '/img/carolina/polk1.jpeg', caption: 'Sun bath' },
    ],
  },
};

export default {
  name: 'CarolinaBlue',
  data() {
    return {
      tileError: false,
      selectedPlace: null,
      popupPos: { x: 0, y: 0 },
      lightbox: { open: false, index: 0 },
      places: PLACES,
      _closeTimer: null,
    };
  },
  computed: {
    currentPlace() {
      return this.selectedPlace ? this.places[this.selectedPlace] : null;
    },
    popupStyle() {
      if (!this.currentPlace) return {};
      const count = this.currentPlace.photos.length;
      const mapW = this.$refs.mapEl ? this.$refs.mapEl.offsetWidth : 800;
      const w = Math.min(count * SLOT_W + (count - 1) * SLOT_GAP + POPUP_PAD, mapW - 16);
      const left = Math.max(w / 2 + 8, Math.min(this.popupPos.x, mapW - w / 2 - 8));
      return {
        left: left + 'px',
        top: Math.max(220, this.popupPos.y - 70) + 'px',
        transform: 'translate(-50%, -100%)',
        width: w + 'px',
      };
    },
  },
  mounted() {
    this.initMap();
    this._resizeObserver = new ResizeObserver(() => this._map?.resize());
    this._resizeObserver.observe(this.$refs.mapEl);
  },
  beforeUnmount() {
    clearTimeout(this._closeTimer);
    this._resizeObserver?.disconnect();
    if (this._map) { this._map.remove(); this._map = null; }
  },
  methods: {
    initMap() {
      this._markers = {};
      try {
        this._map = new MapLibreMap({
          container: this.$refs.mapEl,
          style: BRIGHT_STYLE,
          center: [-79.0484, 35.9121],
          zoom: 15.8,
          maxZoom: 19,
          attributionControl: { compact: true },
        });
      } catch (error) {
        this.tileError = true;
        return;
      }
      const map = this._map;
      map.fitBounds([[-79.0504, 35.91006], [-79.04451, 35.9145912]], {
        padding: { top: 90, bottom: 75, left: 55, right: 55 }, maxZoom: 15.3, duration: 0,
      });
      map.jumpTo({ pitch: 58, bearing: -20 });
      map.addControl(new NavigationControl({ visualizePitch: true }), 'top-left');
      map.on('error', () => { this.tileError = true; });
      map.on('style.load', () => {
        const label = map.getStyle().layers.find(layer => layer.type === 'symbol');
        if (!map.getLayer('campus-buildings-3d')) {
          map.addLayer({
            id: 'campus-buildings-3d',
            type: 'fill-extrusion',
            source: 'openmaptiles',
            'source-layer': 'building',
            minzoom: 14,
            filter: ['!=', ['get', 'hide_3d'], true],
            layout: { visibility: 'visible' },
            paint: {
              'fill-extrusion-color': '#d6d1c8',
              'fill-extrusion-height': ['coalesce', ['get', 'render_height'], 8],
              'fill-extrusion-base': ['coalesce', ['get', 'render_min_height'], 0],
              'fill-extrusion-opacity': 0.9,
            },
          }, label?.id);
        }
      });
      map.on('click', () => this.closePopup());
      Object.entries(PLACES).forEach(([id, place]) => {
        const element = document.createElement('button');
        element.type = 'button';
        element.className = 'campus-photo-marker';
        element.setAttribute('aria-label', `View photos: ${place.name}`);
        element.title = place.name;
        const image = document.createElement('img');
        image.src = place.photos[0].src;
        image.alt = '';
        element.appendChild(image);
        const marker = new Marker({ element, anchor: 'bottom', pitchAlignment: 'viewport' })
          .setLngLat([place.latlng[1], place.latlng[0]])
          .addTo(map);
        this._markers[id] = marker;
        const showPreview = () => {
          clearTimeout(this._closeTimer);
          if (this.lightbox.open) return;
          this.selectedPlace = id;
          this.popupPos = map.project(marker.getLngLat());
        };
        element.addEventListener('mouseenter', showPreview);
        element.addEventListener('mouseleave', this.scheduleClose);
        element.addEventListener('focus', showPreview);
        element.addEventListener('click', event => {
          event.stopPropagation();
          showPreview();
        });
      });
      map.on('move', () => {
        if (this.selectedPlace) this.popupPos = map.project(this._markers[this.selectedPlace].getLngLat());
      });
    },

    retryTiles() {
      this.tileError = false;
      if (!this._map) { this.initMap(); return; }
      this._map.resize();
      this._map.setStyle(BRIGHT_STYLE, { diff: false });
    },

    scheduleClose() {
      if (this.lightbox.open) return;
      clearTimeout(this._closeTimer);
      this._closeTimer = setTimeout(() => this.closePopup(), 200);
    },

    cancelClose() {
      clearTimeout(this._closeTimer);
    },

    closePopup() {
      if (this.selectedPlace && this._markers[this.selectedPlace]) {
        this._markers[this.selectedPlace].getElement().style.opacity = '1';
      }
      this.selectedPlace = null;
      this.lightbox.open = false;
    },

    openLightbox(index) {
      clearTimeout(this._closeTimer);
      this.lightbox = { open: true, index };
    },
  },
};
</script>

